const CHAIN = "base-sepolia";
const USDC_CONTRACT = "0x036CbD53842c5426634e7929541eC2318f3dCF7e";
const AMOUNT = "0.001";

async function getWalletAddress(wallet) {
  if (!wallet) {
    return undefined;
  }
  if (wallet.address) {
    return wallet.address;
  }
  if (Array.isArray(wallet.addresses) && wallet.addresses.length > 0) {
    return wallet.addresses[0]?.address;
  }
  if (wallet.walletAddress) {
    return wallet.walletAddress;
  }
  return undefined;
}

async function main() {
  const apiKey = process.env.CROSSMINT_API_KEY;
  const signerSecret = process.env.SIGNER_SECRET;

  let senderAddress = "mock-sender";
  let receiverAddress = "mock-receiver";
  let transferStatus = "mock";
  let transferAttempted = false;

  try {
    if (!apiKey || !signerSecret) {
      throw new Error("Missing CROSSMINT_API_KEY or SIGNER_SECRET");
    }

    const crossmint = createCrossmint({ apiKey });

    const senderWallet = await crossmint.wallets.getOrCreate({
      walletLocator: "userId:sender-001",
      chain: CHAIN,
      type: "evm-smart-wallet",
      config: {
        recovery: {
          type: "server",
          signer: {
            secret: signerSecret,
          },
        },
      },
    });

    const receiverWallet = await crossmint.wallets.getOrCreate({
      walletLocator: "userId:receiver-001",
      chain: CHAIN,
      type: "evm-smart-wallet",
      config: {
        recovery: {
          type: "server",
          signer: {
            secret: signerSecret,
          },
        },
      },
    });

    senderAddress = (await getWalletAddress(senderWallet)) || senderAddress;
    receiverAddress = (await getWalletAddress(receiverWallet)) || receiverAddress;

    transferAttempted = true;
    await crossmint.wallets.transfer({
      from: "userId:sender-001",
      to: receiverAddress,
      token: {
        chain: CHAIN,
        type: "erc20",
        contractAddress: USDC_CONTRACT,
      },
      amount: AMOUNT,
    });

    transferStatus = "submitted";
  } catch (error) {
    if (transferAttempted) {
      transferStatus = "failed";
    }
  } finally {
    const log = {
      sender_chain: CHAIN,
      receiver_chain: CHAIN,
      amount: AMOUNT,
      token: "USDC",
      sender_address: senderAddress,
      receiver_address: receiverAddress,
      transfer_status: transferStatus,
    };

    await fs.writeFile("/home/user/transfer_log.json", JSON.stringify(log, null, 2));
  }
}

main().catch(async (error) => {
  const fallbackLog = {
    sender_chain: CHAIN,
    receiver_chain: CHAIN,
    amount: AMOUNT,
    token: "USDC",
    sender_address: "mock-sender",
    receiver_address: "mock-receiver",
    transfer_status: "failed",
  };

  await fs.writeFile("/home/user/transfer_log.json", JSON.stringify(fallbackLog, null, 2));

